export interface Customer { active: boolean; level: 'gold' | 'silver' }
/** Current delivery fee waiver policy. */
export function canWaiveDeliveryFee(customer: Customer, totalCents: number): boolean {
  return customer.active && customer.level === 'gold' && totalCents >= 5000;
}

src/checkout/quote.ts:
import {canWaiveDeliveryFee, type Customer} from '../domain/rules';
export function quoteOrder(customer: Customer, totalCents: number) {
  return {deliveryCents: canWaiveDeliveryFee(customer, totalCents) ? 0 : 700};
}

